const AGE_BANDS=[{d:1,key:"blue",label:"0–1 day"},{d:3,key:"green",label:"1–3 days"},{d:5,key:"orange",label:"3–5 days"},{d:10,key:"purple",label:"5–10 days"},{d:Infinity,key:"red",label:"10+ days"}];
const CATEGORY_INTROS={top:"The highest-impact stories across the feed, ranked for importance and recency.",x:"Major issues drawing sustained public attention and reaction.",underreported:"Important reporting receiving less supporting coverage across the source pool.",world:"International developments with meaningful public, economic, security or humanitarian impact.",us:"United States news from national and regional sources.",presidential:"White House, presidential actions and administration developments.",federal:"Congress, federal agencies, courts and national government developments.",legislation:"Bills, laws, rules and official policy actions with primary-source context when available.",nm:"Statewide New Mexico reporting.",local:"Location-aware reporting focused on your local market and nearby communities.",region:"Regional reporting selected for your broader geographic area.",technology:"Technology, AI, cybersecurity, devices and computing.",gaming:"Gaming, hardware, platforms, studios and releases.",military:"Military, defense, security and active-conflict developments.",entertainment:"Major entertainment, careers, awards, family news, releases and industry developments.",christian:"Christian-centered reporting ranked by relevance, significance, freshness and breadth of independent coverage."};
const sourceMarks=[[/(reuters)/i,"R"],[/associated press|\bap\b/i,"AP"],[/\bnpr\b/i,"NPR"],[/\bcbs\b/i,"CBS"],[/\bnbc\b/i,"NBC"],[/bbc/i,"BBC"],[/congress\.gov/i,"CG"],[/federal register/i,"FR"],[/propublica/i,"PP"]];
const stop=new Set("the and for with from into after before about this that says said new news latest update report reports world united states will are was were has have had not but its their his her who what when where why how".split(" "));
const UNDERREPORTED_SORTS=[["signal","Underreported signal"],["newest","Newest"],["oldest","Oldest"],["most-sources","Most supporting sources"],["least-sources","Least supporting sources"]];
export function esc(value){return String(value??"").replace(/[&<>"']/g,ch=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[ch]))}
function formatDate(value){const dt=new Date(value);if(Number.isNaN(dt.getTime()))return "";return new Intl.DateTimeFormat(undefined,{month:"short",day:"numeric",hour:"numeric",minute:"2-digit"}).format(dt)}
function ageBand(value){const ts=Date.parse(value||"");if(!Number.isFinite(ts))return "";const delta=Date.now()-ts;const days=Math.max(0,delta/86400000);return (AGE_BANDS.find(x=>days<x.d)||{key:"red"}).key}
function newBadgeBand(value){const ts=Date.parse(value||"");if(!Number.isFinite(ts))return "";const hours=Math.max(0,(Date.now()-ts)/3600000);if(hours<3)return "cyan";if(hours<6)return "green";if(hours<10)return "tangerine";return ""}
function sourceMark(source){return sourceMarks.find(([p])=>p.test(source||""))?.[1]||String(source||"?").split(/\s+/).filter(Boolean).slice(0,2).map(x=>x[0]).join("").toUpperCase().slice(0,3)||"?"}
function terms(text){return new Set(String(text||"").toLowerCase().replace(/[^a-z0-9]+/g," ").split(/\s+/).filter(w=>w.length>=4&&!stop.has(w)))}
const relatedCache=new WeakMap();function relatedFor(story,store,max=3,category=null){let cache=relatedCache.get(store.feed);if(!cache){cache=new Map();relatedCache.set(store.feed,cache)}const key=`${story.id}|${category||"*"}|${max}`;if(cache.has(key))return cache.get(key);const base=terms(story.title);if(base.size<2){cache.set(key,[]);return[]}const result=store.allStories().filter(other=>other.id!==story.id&&(!category||other.category===category)).map(other=>{const o=terms(other.title),hit=[...base].filter(x=>o.has(x)).length;return{other,score:hit/Math.max(1,Math.min(base.size,o.size))}}).filter(x=>x.score>=.45).sort((a,b)=>b.score-a.score||Date.parse(b.other.published_at)-Date.parse(a.other.published_at)).slice(0,max).map(x=>x.other);cache.set(key,result);return result}
function normalized(v){return String(v||"").toLowerCase().replace(/\s+/g," ").trim()}
function matchesSuppressed(story,pools,category){const url=normalized(story.url),title=normalized(story.title),source=normalized(story.source);const same=(record,requireCategory)=>{if(requireCategory&&normalized(record.category||record.tab)!==normalized(category))return false;const ru=normalized(record.url_key||record.urlKey||record.url);if(ru&&url&&ru===url)return true;return normalized(record.title_key||record.titleKey||record.title)===title&&normalized(record.source_key||record.sourceKey||record.source)===source};return(pools.get("D")||[]).some(r=>same(r,false))||["NR","NW"].some(reason=>(pools.get(reason)||[]).some(r=>same(r,true)))}
function locationRelevant(story,category,location){if(!location||!["local","region"].includes(category))return true;const state=String(location.state||"").toUpperCase();if(category==="local"){if(story.market&&location.city&&normalized(story.market)===normalized(location.city))return true;return !story.state||String(story.state).toUpperCase()===state}if(category==="region"){if(!story.region)return true;return story.region===location.region}return true}
function sectionHead(label,shown,total,intro="",extra=""){return `<div class="section-head"><div><h2>${esc(label)}</h2>${intro?`<p class="section-intro">${esc(intro)}</p>`:""}</div><div class="section-stats"><span>${shown} of ${total}</span>${extra}</div></div>`}
function legend(){return `<div class="legend" aria-label="Story age colors and article feedback controls">${AGE_BANDS.map(x=>`<span><i class="swatch ${x.key}"></i>${x.label}</span>`).join("")}<span class="legend-divider"></span><span><b>D</b>Duplicate</span><span><b>NR</b>Not Relevant</span><span><b>NW</b>Not Wanted</span></div>`}
function feedbackButtons(){return `<div class="feedback-controls" role="group" aria-label="Article feedback"><button type="button" data-feedback="D" title="Duplicate">D · Duplicate</button><button type="button" data-feedback="NR" title="Not Relevant">NR · Not Relevant</button><button type="button" data-feedback="NW" title="Not Wanted">NW · Not Wanted</button></div>`}
function infiniteSentinel(){return '<div class="infinite-sentinel" data-infinite-sentinel><button type="button" data-action="load-more" hidden aria-hidden="true" tabindex="-1"></button></div>'}
function cardHtml(story,store,category,options={}){const rel=relatedFor(story,store,3),band=ageBand(story.published_at),saved=store.isBookmarked(story.id),newBand=newBadgeBand(story.published_at);const related=rel.length?`<details class="related"><summary>Coverage · ${rel.length+1} sources</summary>${rel.map(r=>`<a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">${esc(r.title)} <span>· ${esc(r.source)}</span></a>`).join("")}</details>`:"";const signal=options.underreported?Math.max(50,Math.min(96,96-rel.length*10)):0;const entConnection=options.entertainment?relatedFor(story,store,2,"underreported"):[];const entLinks=entConnection.length?`<div class="connection"><strong>UNDERREPORTED CONNECTION</strong>${entConnection.map(r=>`<a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">${esc(r.title)} <span>· ${esc(r.source)}</span></a>`).join("")}</div>`:"";return `<article class="story-card age-${band}" data-story-id="${esc(story.id)}" data-category="${esc(category)}"><div class="card-topline"><span class="source-mark" aria-hidden="true">${esc(sourceMark(story.source))}</span><span class="story-meta">${esc(formatDate(story.published_at))}${story.source?` · ${esc(story.source)}`:""}</span>${newBand?`<span class="new-badge new-badge-${newBand}">NEW</span>`:""}${options.label?`<span class="category-pill">${esc(options.label)}</span>`:""}${signal?`<span class="signal" title="Heuristic: higher means less supporting coverage was found">Underreported ${signal}/100</span>`:""}<button class="bookmark-btn ${saved?"saved":""}" type="button" data-bookmark="${esc(story.id)}" aria-label="${saved?"Remove bookmark":"Save bookmark"}" title="${saved?"Remove bookmark":"Save bookmark"}">${saved?"★":"☆"}</button></div><h3><a href="${esc(story.url)}" target="_blank" rel="noopener noreferrer">${esc(story.title)}</a></h3>${story.summary?`<p class="story-summary">${esc(story.summary)}</p>`:""}${story.why_matters?`<p class="story-why"><strong>WHY IT MATTERS</strong><span>${esc(story.why_matters)}</span></p>`:""}${entLinks}${related}${feedbackButtons()}</article>`}
function christianScore(story,store){
 const text=normalized(`${story.title} ${story.summary||""} ${story.why_matters||""}`);
 const christian=/christian|christianity|church|jesus|bible|biblical|gospel|faith|pastor|missionar|persecut|religious freedom|jerusalem|israel/.test(text)?25:12;
 const significance=/persecut|war|attack|killed|arrest|law|court|government|election|president|congress|supreme court|global|million|crisis|archaeolog|discover/.test(text)?20:10;
 const age=Math.max(0,(Date.now()-(Date.parse(story.published_at)||Date.now()))/3600000),fresh=age<6?15:age<24?12:age<72?8:age<120?5:2;
 const rel=relatedFor(story,store,5),independent=new Set(rel.map(r=>normalized(r.source))).size,breadth=Math.min(10,independent*3);
 const interest=/archaeolog|discover|history|ancient|movie|film|music|actor|culture|science|artifact|bible|jerusalem/.test(text)?10:5;
 const source=/(associated press|reuters|bbc|religion news service|christianity today|christian today|cbn|christian post|open doors|voice of the martyrs)/i.test(story.source||"")?10:6;
 return Math.min(100,christian+significance+fresh+breadth+interest+source+10);
}
function christianTopic(story){const t=normalized(`${story.title} ${story.summary||""}`);if(/persecut|religious freedom|martyr/.test(t))return"WORLD / PERSECUTION";if(/archaeolog|ancient|artifact|biblical history|jerusalem|israel/.test(t))return"BIBLICAL HISTORY / ISRAEL";if(/movie|film|music|actor|entertain|culture/.test(t))return"CULTURE / ENTERTAINMENT";if(/president|congress|government|election|court|law|politic/.test(t))return"PUBLIC LIFE";return"CHRISTIAN / CHURCH"}
function christianRelated(story,store){const same=relatedFor(story,store,6).filter(r=>r.url&&r.source&&normalized(r.source)!==normalized(story.source));const seen=new Set();return same.filter(r=>{const k=normalized(r.source);if(seen.has(k))return false;seen.add(k);return true}).slice(0,3)}
