function dailyVerse(){const now=new Date(),day=Date.UTC(now.getFullYear(),now.getMonth(),now.getDate())/86400000,index=((Math.floor(day)%DAILY_VERSES.length)+DAILY_VERSES.length)%DAILY_VERSES.length,[ref,text]=DAILY_VERSES[index];return `<div class="daily-verse" aria-label="Daily Bible verse"><span class="daily-verse-label">DAILY VERSE</span><span class="daily-verse-text">“${esc(text)}”</span><strong>${esc(ref)} · KJV</strong></div>`}
function christian({store,root}){const category="christian",base=store.categoryStories(category).filter(s=>!matchesSuppressed(s,store.suppressed,category)),scored=base.map(story=>({story,score:christianScore(story,store)}));scored.sort((a,b)=>b.score-a.score||(Date.parse(b.story.published_at)||0)-(Date.parse(a.story.published_at)||0));const all=scored.map(x=>x.story),scoreMap=new Map(scored.map(x=>[x.story.id,x.score])),shown=Math.min(store.shown(category),all.length),list=all.slice(0,shown),meta=store.feed.categories[category];const cards=list.map(story=>{const score=scoreMap.get(story.id)||0,related=christianRelated(story,store),band=ageBand(story.published_at),saved=store.isBookmarked(story.id),newBand=newBadgeBand(story.published_at),coverage=related.length?`<div class="connection christian-related"><strong>RELATED COVERAGE</strong>${related.map(r=>`<a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">${esc(r.source)} <span>· ${esc(r.title)}</span></a>`).join("")}</div>`:"";return `<article class="story-card age-${band}" data-story-id="${esc(story.id)}" data-category="christian"><div class="card-topline"><span class="source-mark" aria-hidden="true">${esc(sourceMark(story.source))}</span><span class="story-meta">${esc(formatDate(story.published_at))}${story.source?` · ${esc(story.source)}`:""}</span>${newBand?`<span class="new-badge new-badge-${newBand}">NEW</span>`:""}<span class="category-pill">${esc(christianTopic(story))}</span><span class="signal" title="Christian desk priority: relevance, significance, freshness, source quality and independent coverage">Priority ${score}</span><button class="bookmark-btn ${saved?"saved":""}" type="button" data-bookmark="${esc(story.id)}" aria-label="${saved?"Remove bookmark":"Save bookmark"}">${saved?"★":"☆"}</button></div><h3><a href="${esc(story.url)}" target="_blank" rel="noopener noreferrer">${esc(story.title)}</a></h3>${story.summary?`<p class="story-summary">${esc(story.summary)}</p>`:""}${story.why_matters?`<p class="story-why"><strong>WHY IT MATTERS</strong><span>${esc(story.why_matters)}</span></p>`:""}${coverage}${feedbackButtons()}</article>`}).join("");root.innerHTML=dailyVerse()+sectionHead(meta.label,shown,all.length,CATEGORY_INTROS.christian)+legend()+`<div class="story-list christian-list">${cards}</div>${shown<all.length?infiniteSentinel():""}`}
function generic({store,root}){const category=store.active,all=store.categoryStories(category).filter(story=>locationRelevant(story,category,store.location)).filter(story=>!matchesSuppressed(story,store.suppressed,category)),shown=Math.min(store.shown(category),all.length),list=all.slice(0,shown),meta=store.feed.categories[category];root.innerHTML=sectionHead(meta.label,shown,all.length,CATEGORY_INTROS[category]||"")+legend()+`<div class="story-list">${list.map(story=>cardHtml(story,store,category)).join("")}</div>${shown<all.length?infiniteSentinel():""}${!list.length?`<div class="empty">No ${esc(meta.label)} stories are available right now.</div>`:""}`}
function underreportedCard(story,store,index){const band=ageBand(story.published_at),saved=store.isBookmarked(story.id),count=Number(story.supporting_source_count||0),score=Number(story.coverage_score||0),related=Array.isArray(story.related)?story.related:[];const footnotes=related.length?`<div class="related"><summary style="list-style:none;cursor:default;color:var(--text)">CONNECTIONS & FOOTNOTES</summary>${related.map((r,i)=>`<a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">${i+1}. ${esc(r.title)} <span>· ${esc(r.source)}${r.published_at?` · ${esc(formatDate(r.published_at))}`:""}</span></a>`).join("")}</div>`:"";const block=(label,text)=>text?`<p class="story-why"><strong>${label}</strong><span>${esc(text)}</span></p>`:"";return `<article class="story-card age-${band}" data-story-id="${esc(story.id)}" data-category="underreported"><div class="card-topline"><span class="category-pill">${esc(story.coverage_label||"UNDERREPORTED")}</span>${score?`<span class="signal">Underreported signal ${score}/100 · ${count} supporting source${count===1?"":"s"}</span>`:""}<button class="bookmark-btn ${saved?"saved":""}" type="button" data-bookmark="${esc(story.id)}" aria-label="${saved?"Remove bookmark":"Save bookmark"}" title="${saved?"Remove bookmark":"Save bookmark"}">${saved?"★":"☆"}</button></div><h3><a href="${esc(story.url)}" target="_blank" rel="noopener noreferrer">${index+1}. ${esc(story.title)}</a></h3>${block("WHY IT MATTERS",story.why_matters)}${block("WHAT HAPPENED",story.what_happened||story.summary)}${block("WHAT'S BEING MISSED",story.what_is_missing)}${block("BACKGROUND",story.background)}${block("WHAT HAPPENS NEXT",story.what_next)}${footnotes}<div class="story-meta" style="margin-top:9px">${esc(formatDate(story.published_at))}${story.source?` · ${esc(story.source)}`:""}</div>${feedbackButtons()}</article>`}
function sortUnderreported(rows,mode){const list=[...rows],date=row=>Date.parse(row.published_at||0)||0,sources=row=>Number(row.supporting_source_count||0),signal=row=>Number(row.coverage_score||0);if(mode==="newest")return list.sort((a,b)=>date(b)-date(a)||signal(b)-signal(a));if(mode==="oldest")return list.sort((a,b)=>date(a)-date(b)||signal(b)-signal(a));if(mode==="most-sources")return list.sort((a,b)=>sources(b)-sources(a)||signal(b)-signal(a)||date(b)-date(a));if(mode==="least-sources")return list.sort((a,b)=>sources(a)-sources(b)||signal(b)-signal(a)||date(b)-date(a));return list.sort((a,b)=>signal(b)-signal(a)||sources(a)-sources(b)||date(b)-date(a))}
function underreportedSortControl(store){return `<label>Sort <select data-underreported-sort aria-label="Sort Underreported stories">${UNDERREPORTED_SORTS.map(([value,label])=>`<option value="${value}"${store.underreportedSort===value?" selected":""}>${label}</option>`).join("")}</select></label>`}
function underreported(ctx){const{store,root}=ctx,category="underreported",base=store.categoryStories(category).filter(s=>!matchesSuppressed(s,store.suppressed,category)),all=sortUnderreported(base,store.underreportedSort),shown=Math.min(store.shown(category),all.length),list=all.slice(0,shown),meta=store.feed.categories[category];root.innerHTML=sectionHead(meta.label,shown,all.length,CATEGORY_INTROS[category],underreportedSortControl(store))+legend()+`<div class="story-list">${list.map((story,i)=>underreportedCard(story,store,i)).join("")}</div>${shown<all.length?infiniteSentinel():""}`}
function entertainment({store,root}){const category="entertainment",all=store.categoryStories(category).filter(s=>!matchesSuppressed(s,store.suppressed,category)),shown=Math.min(store.shown(category),all.length),list=all.slice(0,shown),meta=store.feed.categories[category];root.innerHTML=sectionHead(meta.label,shown,all.length,CATEGORY_INTROS[category])+legend()+`<div class="story-list">${list.map(story=>{const text=`${story.title} ${story.summary}`.toLowerCase();const label=/award|oscar|emmy|grammy/.test(text)?"AWARDS":/family|married|baby|children|philanthrop/.test(text)?"PEOPLE / FAMILY":/box office|film|movie|series|television|tv/.test(text)?"FILM / TV":/music|album|tour|concert/.test(text)?"MUSIC":"ENTERTAINMENT";return cardHtml(story,store,category,{entertainment:true,label})}).join("")}</div>${shown<all.length?infiniteSentinel():""}`}
function legislation({store,root}){const category="legislation",all=store.categoryStories(category).filter(s=>!matchesSuppressed(s,store.suppressed,category)),shown=Math.min(store.shown(category),all.length),list=all.slice(0,shown),meta=store.feed.categories[category];const cards=list.map(story=>{const id=(story.title.match(/\b(?:H\.?R\.?|S\.?|H\.Res\.|S\.Res\.|H\.J\.Res\.|S\.J\.Res\.)\s*\d+\b/i)||[])[0]||"";const official=/congress|federal register|white house|govinfo/i.test(story.source||"");return `<article class="story-card legislation-card age-${ageBand(story.published_at)}" data-story-id="${esc(story.id)}" data-category="legislation"><div class="leg-pills">${id?`<span>${esc(id)}</span>`:""}${official?'<span>OFFICIAL SOURCE</span>':""}<span>${esc(story.source||"Source")}</span></div><h3><a href="${esc(story.url)}" target="_blank" rel="noopener noreferrer">${esc(story.title)}</a></h3>${story.summary?`<p class="story-summary">${esc(story.summary)}</p>`:""}${story.why_matters?`<p class="story-why"><strong>WHY IT MATTERS</strong><span>${esc(story.why_matters)}</span></p>`:""}${feedbackButtons()}</article>`}).join("");root.innerHTML=sectionHead(meta.label,shown,all.length,CATEGORY_INTROS[category])+legend()+`<div class="story-list">${cards}</div>${shown<all.length?infiniteSentinel():""}`}
function nflState(game){const state=String(game.state||"").toLowerCase();if(state==="in")return"live";if(state==="post")return"final";return"upcoming"}
function keepNflGame(game){if(nflState(game)!=="final")return true;const ts=Date.parse(game.date||"");if(!Number.isFinite(ts))return true;const d=new Date(ts),cutoff=new Date(d.getFullYear(),d.getMonth(),d.getDate()+1,6,0,0,0).getTime();return Date.now()<cutoff}
function sortNflGames(rows){const rank={live:0,upcoming:1,final:2};return [...rows].filter(keepNflGame).sort((a,b)=>{const sa=nflState(a),sb=nflState(b),r=rank[sa]-rank[sb];if(r)return r;const ta=Date.parse(a.date||0)||0,tb=Date.parse(b.date||0)||0;return sa==="final"?tb-ta:ta-tb})}
function nflKickoff(value){const d=new Date(value);if(Number.isNaN(d.getTime()))return{local:"",eastern:""};const options={weekday:"short",month:"short",day:"numeric",hour:"numeric",minute:"2-digit",timeZoneName:"short"};const local=new Intl.DateTimeFormat(undefined,options).format(d),zone=Intl.DateTimeFormat().resolvedOptions().timeZone||"";const eastern=zone==="America/New_York"?"":new Intl.DateTimeFormat(undefined,{...options,timeZone:"America/New_York"}).format(d);return{local,eastern}}
function nflTeamAccent(team){for(const raw of [team?.color,team?.alternateColor]){const value=String(raw||"").replace("#","");if(/^[0-9a-f]{6}$/i.test(value)){const n=parseInt(value,16),r=n>>16,g=(n>>8)&255,b=n&255;if((.2126*r+.7152*g+.0722*b)<210)return`#${value}`}}return"#64748b"}
function nflLogo(team,label){return team?.logo?`<img src="${esc(team.logo)}" alt="${esc(label)} logo" loading="lazy" style="width:24px;height:24px;object-fit:contain">`:`<span style="width:24px;height:24px;border-radius:50%;display:inline-grid;place-items:center;font-size:8px;font-weight:900;background:var(--surface-2);border:1px solid var(--line)">${esc(team?.abbr||"NFL")}</span>`}
