  const status=String(game.tank01Status||"pending");
  const available=status==="live";
  const tankRows=available?(Array.isArray(game.tank01Plays)?game.tank01Plays:[]):[];
  const espnRows=[...(game.gameCenter?.plays||game.plays||[])].filter(p=>p&&p.text);
  const rows=(available&&tankRows.length?tankRows:espnRows).slice(-6).reverse();
  const source=available&&tankRows.length?"Tank01":"ESPN fallback";
  const info=status==="not-configured"?"Tank01 requires its Cloudflare API key; showing ESPN updates until connected.":status==="unavailable"?"Tank01 is temporarily unavailable; ESPN updates remain available.":status==="pending"?"Connecting to Tank01; ESPN updates shown until connected.":available&&!tankRows.length?"Tank01 connected; waiting for new play-by-play.":"";
