function nflPct(value){return `${Math.round(Number(value)||0)}%`}
function nflStandingRow(row){const diff=`${row.diff>0?"+":""}${Math.round(row.diff)}`;return `<tr class="${row.projected?"projected":""}"><td class="nfl-seed">${row.rank}</td><td class="nfl-team-cell"><img src="${esc(row.logo)}" alt="" loading="lazy"><strong>${esc(row.abbr)}</strong><small>${esc(row.division)}</small></td><td>${row.wins}</td><td>${row.losses}</td><td class="nfl-diff ${row.diff>0?"positive":row.diff<0?"negative":""}">${diff}</td><td>${esc(row.streak)}</td><td><span class="nfl-odds ${row.playoff>=65?"strong":row.playoff>=40?"bubble":"low"}">${nflPct(row.playoff)}</span></td><td>${nflPct(row.superBowl)}</td></tr>`}
function nflSeasonScorecard(data){const rows=nflStandingsRows(data);if(!rows.length)return `<section class="nfl-season-card"><div class="nfl-season-head"><div><span>SEASON SCORECARD</span><h3>Standings & playoff outlook</h3></div></div><div class="nfl-season-empty">Standings are updating from the live NFL feed.</div></section>`;const afc=rows.filter(r=>r.conference==="AFC").sort((a,b)=>a.rank-b.rank),nfc=rows.filter(r=>r.conference==="NFC").sort((a,b)=>a.rank-b.rank),afcTop=[...afc].sort((a,b)=>b.power-a.power)[0],nfcTop=[...nfc].sort((a,b)=>b.power-a.power)[0],contenders=[...rows].sort((a,b)=>b.superBowl-a.superBowl).slice(0,5);const table=(label,list)=>`<div class="nfl-conference"><div class="nfl-conference-title"><strong>${label}</strong><span>Top 7 shaded = projected field</span></div><div class="nfl-standings-scroll"><table class="nfl-standings"><thead><tr><th>#</th><th>TEAM</th><th>W</th><th>L</th><th>+/-</th><th>STRK</th><th>PO%</th><th>SB%</th></tr></thead><tbody>${list.map(nflStandingRow).join("")}</tbody></table></div></div>`;const matchup=afcTop&&nfcTop?`<div class="nfl-prediction-main"><span>PROJECTED SUPER BOWL MATCHUP</span><div><img src="${esc(afcTop.logo)}" alt=""><strong>${esc(afcTop.abbr)}</strong><em>vs</em><strong>${esc(nfcTop.abbr)}</strong><img src="${esc(nfcTop.logo)}" alt=""></div><small>Current model · record + point differential + recent streak + conference position</small></div>`:"";return `<section class="nfl-season-card"><div class="nfl-season-head"><div><span>SEASON SCORECARD</span><h3>Standings & playoff outlook</h3></div><div class="nfl-model-note">Live standings · model estimates</div></div>${matchup}<div class="nfl-contenders">${contenders.map((r,i)=>`<div><span>${i+1}</span><img src="${esc(r.logo)}" alt=""><strong>${esc(r.abbr)}</strong><small>${nflPct(r.superBowl)} title share</small></div>`).join("")}</div><div class="nfl-conference-grid">${table("AFC",afc)}${table("NFC",nfc)}</div><p class="nfl-model-footnote">PO% and SB% are Underreported model estimates, not sportsbook odds. They update from live standings and become more informative as the season progresses.</p></section>`}
function nfl({store,root}){const games=sortNflGames(store.nfl.games||[]),liveGames=games.filter(g=>nflState(g)==="live"),selected=games.find(g=>String(g.id)===String(store.selectedNfl))||liveGames[0]||null,nextIndex=liveGames.length?-1:games.findIndex(g=>nflState(g)==="upcoming"),allNews=store.categoryStories("nfl").filter(s=>!matchesSuppressed(s,store.suppressed,"nfl")),shownNews=Math.min(store.shown("nfl"),allNews.length),news=allNews.slice(0,shownNews);root.innerHTML=sectionHead("NFL",games.length,games.length,"Live scoreboard, season standings, playoff outlook and NFL news. Kickoff times use your device timezone.",store.nfl.error?'<span class="warn">Data warning</span>':"")+`<div class="nfl-live-note"><strong>Live:</strong> ESPN via Cloudflare · scores refresh about every 5 seconds when viewing · current + upcoming 7 days · kickoff times use your device timezone · finals roll off at 6:00 AM local</div>${nflGameCenter(selected,liveGames,store.nflGameCenterTab)}<div class="nfl-grid">${games.map((g,i)=>nflGameCard(g,i,nextIndex,store.selectedNfl)).join("")}</div>${!games.length?'<div class="empty">No current or upcoming NFL games are available in this scoreboard window.</div>':""}${nflSeasonScorecard(store.nflStandings)}${allNews.length?`<div class="nfl-news-head"><h3>NFL News</h3><span>${shownNews} of ${allNews.length}</span></div><div class="story-list nfl-news-list">${news.map(story=>cardHtml(story,store,"nfl")).join("")}</div>${shownNews<allNews.length?infiniteSentinel():""}`:""}`}
const MOVIE_DAY=86400000;
function movieDay(value){if(!value)return NaN;const text=/^\d{4}-\d{2}-\d{2}$/.test(String(value))?`${value}T12:00:00`:String(value);const ts=Date.parse(text);return Number.isFinite(ts)?ts:NaN}
function movieStatus(movie){const today=new Date();today.setHours(0,0,0,0);const now=today.getTime(),release=movieDay(movie.releaseDate),leaving=movieDay(movie.leavingDate),status=String(movie.status||"").toLowerCase();if(movie.isUpcoming===true||status.includes("upcoming")||(Number.isFinite(release)&&release>now))return["coming","COMING SOON"];if(movie.leavingSoon===true||status.includes("leaving")||(Number.isFinite(leaving)&&leaving>=now&&(leaving-now)/MOVIE_DAY<=7))return["leaving","LEAVING SOON"];if(Number.isFinite(release)){const age=(now-release)/MOVIE_DAY;if(age>=0&&age<=14)return["new","NEW RELEASE"]}return["playing","NOW PLAYING"]}
function movieSortValue(movie){const ts=movieDay(movie.releaseDate);return Number.isFinite(ts)?ts:-Infinity}
function boxOfficeLegend(){return `<div class="legend" aria-label="Box Office color rail legend"><span><i class="swatch" style="background:#06b6d4"></i>Coming soon</span><span><i class="swatch blue"></i>New release</span><span><i class="swatch green"></i>Now playing</span><span><i class="swatch" style="background:#dc2626"></i>Leaving soon</span></div>`}
function compactMovieOverview(value){const text=String(value||"").replace(/\s+/g," ").trim();if(!text||/\b(?:may|can) refer to\b|\bdisambiguation\b|\bis a list of\b/i.test(text))return "";if(text.length<=240)return text;return text.slice(0,237).replace(/\s+\S*$/," ").trim()+"…"}
function movieCard(movie,store){const[state,label]=movieStatus(movie),related=store.categoryStories("entertainment").filter(s=>normalized(`${s.title} ${s.summary}`).includes(normalized(movie.title))).slice(0,2),news=(movie.news||[]).slice(0,2),overview=compactMovieOverview(movie.overview),loc=store.location,showQuery=encodeURIComponent(`${movie.title} showtimes ${[loc?.city,loc?.state].filter(Boolean).join(" ")}`),theaters=movie.theaters||[];const theaterHtml=theaters.length?theaters.map(t=>`<small><b>${esc(t.name||"Theater")}</b>: ${esc((t.showtimes||[]).join(", "))}</small>`).join(""):`<a href="https://www.google.com/search?q=${showQuery}" target="_blank" rel="noopener noreferrer">Find showtimes${loc?.city?` near ${esc(loc.city)}`:""}</a>`;const movieNews=news.length?news.map(n=>`<a href="${esc(n.link)}" target="_blank" rel="noopener noreferrer">${esc(n.title)}</a>`).join(""):related.map(s=>`<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)}</a>`).join("");const artwork=movie.poster?`<img class="movie-poster" src="${esc(movie.poster)}" alt="Poster for ${esc(movie.title)}" loading="lazy">`:`<div class="movie-poster" role="img" aria-label="Poster unavailable for ${esc(movie.title)}"></div>`;return `<article class="movie-card ${state}" data-rail-meaning="movie-status">${artwork}<div class="movie-body"><div class="movie-topline"><span class="movie-status">${label}</span>${movie.releaseDate?`<span class="movie-pill">${state==="coming"?"Release":"Released"} ${esc(movie.releaseDate)}</span>`:""}${movie.rating?`<span class="movie-pill">${esc(movie.rating)}</span>`:""}${movie.runtime?`<span class="movie-pill">${esc(movie.runtime)}</span>`:""}${movie.voteAverage?`<span class="movie-pill">★ ${Number(movie.voteAverage).toFixed(1)}</span>`:""}</div><h3>${movie.url?`<a href="${esc(movie.url)}" target="_blank" rel="noopener noreferrer">${esc(movie.title)}</a>`:esc(movie.title)}</h3>${overview?`<p>${esc(overview)}</p>`:""}<div class="movie-showtimes"><strong>Local showtimes</strong>${theaterHtml}</div>${movieNews?`<div class="movie-news"><strong>MOVIE NEWS</strong>${movieNews}</div>`:""}</div></article>`}
function boxoffice({store,root}){const key=m=>String(m?.tmdbId||"")||String(m?.title||"").toLowerCase().replace(/&/g,"and").replace(/[^a-z0-9]+/g," ").trim(),movies=[...new Map((store.boxoffice.movies||[]).filter(Boolean).map(m=>[key(m),m])).values()],newest=movies.filter(m=>movieStatus(m)[0]==="new").sort((a,b)=>movieSortValue(b)-movieSortValue(a)||String(a.title||"").localeCompare(String(b.title||""))),playing=movies.filter(m=>movieStatus(m)[0]==="playing").sort((a,b)=>movieSortValue(b)-movieSortValue(a)||String(a.title||"").localeCompare(String(b.title||""))),leaving=movies.filter(m=>movieStatus(m)[0]==="leaving").sort((a,b)=>(movieDay(a.leavingDate)-movieDay(b.leavingDate))||String(a.title||"").localeCompare(String(b.title||""))),upcoming=movies.filter(m=>movieStatus(m)[0]==="coming").sort((a,b)=>movieSortValue(a)-movieSortValue(b)||String(a.title||"").localeCompare(String(b.title||"")));const block=(heading,cls,rows)=>rows.length?`<h3 class="box-heading ${cls}">${heading}</h3><div class="movie-list">${rows.map(m=>movieCard(m,store)).join("")}</div>`:"";root.innerHTML=sectionHead("Box Office",movies.length,movies.length,"Newest releases, now playing, leaving soon, upcoming releases, local showtime access and movie-specific coverage.")+boxOfficeLegend()+`${store.boxoffice.error?`<p class="status-note">${esc(store.boxoffice.error)}</p>`:""}${block("🆕 Newest — newest releases first","new",newest)}${block("🎥 Now Playing","playing",playing)}${block("🔴 Leaving Soon — earliest departures first","leaving",leaving)}${block("🩵 Upcoming — next releases first","coming",upcoming)}${!movies.length?'<div class="empty">Box Office data is unavailable in this build.</div>':""}`}
function bookmarks({store,root}){const all=store.bookmarks,shown=Math.min(store.shown("bookmarks"),all.length),list=all.slice(0,shown);root.innerHTML=sectionHead("Bookmarks",shown,all.length,"Stories you saved on this device.")+`<div class="story-list bookmark-section">${list.map(story=>cardHtml(story,store,story.category||"bookmarks")).join("")}</div>${shown<all.length?infiniteSentinel():""}${!list.length?'<div class="empty">No bookmarks yet. Tap ☆ on a story to save it here.</div>':""}`}
export const rendererRegistry=new Map([["nfl",nfl],["boxoffice",boxoffice],["underreported",underreported],["entertainment",entertainment],["legislation",legislation],["bookmarks",bookmarks],["christian",christian]]);
export function renderActive(context){const renderer=rendererRegistry.get(context.store.active)||generic;renderer(context)}
